func TestOptionSpaceRunes(t *testing.T) {
	t.Run("replaces spaces with the given rune", func(t *testing.T) {
		result := unsafepretty.Print("a b", unsafepretty.OptionSpaceRunes('X'))
		require.Equal(t, "aXb", result)
	})

	t.Run("replaces each space with the full rune sequence", func(t *testing.T) {
		result := unsafepretty.Print("a b", unsafepretty.OptionSpaceRunes('X', 'Y', 'Z'))
		require.Equal(t, "aXYZb", result)
	})

	t.Run("empty runes removes spaces entirely", func(t *testing.T) {
		result := unsafepretty.Print("a b", unsafepretty.OptionSpaceRunes())
		require.Equal(t, "ab", result)
	})

	t.Run("each space is independently replaced", func(t *testing.T) {
		result := unsafepretty.Print("a  b", unsafepretty.OptionSpaceRunes('X'))
		require.Equal(t, "aXXb", result)
	})

	t.Run("supports unicode runes", func(t *testing.T) {
		result := unsafepretty.Print("a b", unsafepretty.OptionSpaceRunes('·'))
		require.Equal(t, "a·b", result)
	})

	t.Run("does not affect newlines", func(t *testing.T) {
		result := unsafepretty.Print("a\nb", unsafepretty.OptionSpaceRunes('X'))
		require.Equal(t, "a\nb", result)
	})

	t.Run("does not affect tabs", func(t *testing.T) {
		result := unsafepretty.Print("a\tb", unsafepretty.OptionSpaceRunes('X'))
		require.Equal(t, "a\\tb", result)
	})

	t.Run("does not affect carriage returns", func(t *testing.T) {
		result := unsafepretty.Print("a\rb", unsafepretty.OptionSpaceRunes('X'))
		require.Equal(t, "a\\rb", result)
	})

	t.Run("input with no spaces is unchanged", func(t *testing.T) {
		result := unsafepretty.Print("hello", unsafepretty.OptionSpaceRunes('X'))
		require.Equal(t, "hello", result)
	})

	t.Run("leading and trailing spaces are replaced", func(t *testing.T) {
		result := unsafepretty.Print(" a ", unsafepretty.OptionSpaceRunes('·'))
		require.Equal(t, "·a·", result)
	})
}
